"""Workbook cleaner. Importing this module performs no I/O."""
import base64
import copy
import io
import json
import math
import posixpath
import re
import sys
import zipfile
from datetime import date, datetime
from decimal import Decimal, InvalidOperation
from xml.etree import ElementTree as ET

from openpyxl import load_workbook
from openpyxl.utils.datetime import from_excel

S = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
R = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
P = 'http://schemas.openxmlformats.org/package/2006/relationships'
C = 'http://schemas.openxmlformats.org/package/2006/content-types'
NS = {'s': S}


def tag(name):
    return '{' + S + '}' + name


def xml_bytes(root):
    return ET.tostring(root, encoding='utf-8', xml_declaration=True)


def parse_xml(data):
    if b'<!DOCTYPE' in data.upper() or b'<!ENTITY' in data.upper():
        raise ValueError('DTD/entity declarations are unsupported')
    return ET.fromstring(data)


def number(cell):
    value = cell.value
    if cell.data_type in ('e', 'f') or isinstance(value, (bool, date)):
        raise ValueError('Invalid numeric cell')
    if value is None or isinstance(value, str) and not value.strip():
        return 0.0
    if isinstance(value, str):
        value = value.strip()
        if not re.fullmatch(r'[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?', value):
            raise ValueError('Invalid numeric text')
    try:
        result = float(value)
    except (TypeError, ValueError, OverflowError):
        raise ValueError('Invalid number') from None
    if not math.isfinite(result):
        raise ValueError('Nonfinite number')
    return result


def normalized_date(value, epoch):
    if value is None or isinstance(value, str) and not value.strip():
        return None
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        converted = from_excel(value, epoch=epoch)
        if isinstance(converted, datetime):
            return converted.date().isoformat()
        raise ValueError('Date serial does not contain a calendar date')
    if isinstance(value, str):
        text = value.strip()
        try:
            return datetime.fromisoformat(text.replace('Z', '+00:00')).date().isoformat()
        except ValueError:
            pass
        for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%m/%d/%Y', '%d/%m/%Y', '%m-%d-%Y', '%d-%m-%Y', '%d-%b-%Y', '%d %b %Y', '%B %d, %Y'):
            try:
                return datetime.strptime(text, fmt).date().isoformat()
            except ValueError:
                pass
    raise ValueError('Unrecognized date: ' + repr(value))


def column_index(reference):
    result = 0
    for char in re.match(r'[A-Z]+', reference).group():
        result = result * 26 + ord(char) - 64
    return result


def get_cell(row, reference):
    for cell in row.findall(tag('c')):
        if cell.get('r') == reference:
            return cell
    cell = ET.Element(tag('c'), {'r': reference})
    index = column_index(reference)
    for position, existing in enumerate(row):
        if existing.tag == tag('c') and column_index(existing.get('r')) > index:
            row.insert(position, cell)
            break
    else:
        row.append(cell)
    return cell


def set_cell(cell, value=None, formula=None, style=None):
    for child in list(cell):
        if child.tag in (tag('f'), tag('v'), tag('is')):
            cell.remove(child)
    cell.attrib.pop('t', None)
    if style is not None:
        cell.set('s', str(style))
    if formula is not None:
        ET.SubElement(cell, tag('f')).text = formula
        ET.SubElement(cell, tag('v')).text = repr(value)
    elif isinstance(value, str):
        cell.set('t', 'inlineStr')
        text = ET.SubElement(ET.SubElement(cell, tag('is')), tag('t'))
        text.set('{http://www.w3.org/XML/1998/namespace}space', 'preserve')
        text.text = value
    elif value is not None:
        ET.SubElement(cell, tag('v')).text = repr(value)


def clean_workbook(payload):
    encoded = payload['workbook_b64']
    bound = payload['row_bound']
    if type(bound) is not int or not 1 <= bound <= 32:
        raise ValueError('row_bound must be an integer from 1 to 32')
    if not isinstance(encoded, str) or len(encoded) > 200000:
        raise ValueError('Invalid workbook_b64 length')
    raw = base64.b64decode(encoded, validate=True)
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        infos = archive.infolist()
        if len(infos) > 2000 or sum(i.file_size for i in infos) > 20000000:
            raise ValueError('Workbook exceeds decompressed size limits')
        if len({i.filename for i in infos}) != len(infos):
            raise ValueError('Duplicate ZIP entries')
        parts = {i.filename: archive.read(i) for i in infos}
    for name, content in parts.items():
        lower = name.lower()
        if any(token in lower for token in ('vbaproject', 'externallinks/', 'macrosheets/')):
            raise ValueError('Macros and external workbook links are unsupported')
        if name.endswith('.rels'):
            rels = parse_xml(content)
            if any(r.get('TargetMode') == 'External' for r in rels):
                raise ValueError('External relationships are unsupported')

    book = load_workbook(io.BytesIO(raw), data_only=False, keep_links=False)
    if 'Data' not in book.sheetnames:
        raise ValueError('Missing Data sheet')
    data = book['Data']
    headers = [data.cell(1, col).value for col in range(1, 6)]
    if headers != ['ID', 'Date', 'Quantity', 'Price', 'Amount']:
        raise ValueError('Expected Data headers: ID, Date, Quantity, Price, Amount')

    workbook = parse_xml(parts['xl/workbook.xml'])
    relationships = parse_xml(parts['xl/_rels/workbook.xml.rels'])
    sheets = workbook.find(tag('sheets'))
    targets = {rel.get('Id'): rel.get('Target') for rel in relationships}
    paths = {}
    for sheet in sheets:
        target = targets[sheet.get('{' + R + '}id')]
        paths[sheet.get('name')] = posixpath.normpath(target.lstrip('/') if target.startswith('/') else 'xl/' + target)

    styles = parse_xml(parts['xl/styles.xml'])
    fonts = styles.find(tag('fonts'))
    formats = styles.find(tag('cellXfs'))
    bold_styles = {}
    plain_styles = {}

    def transformed_style(style_id, bold=False):
        mapping = bold_styles if bold else plain_styles
        if style_id in mapping:
            return mapping[style_id]
        style = copy.deepcopy(formats[style_id])
        if bold:
            font = copy.deepcopy(fonts[int(style.get('fontId', '0'))])
            for child in list(font):
                if child.tag == tag('b'):
                    font.remove(child)
            ET.SubElement(font, tag('b'), {'val': '1'})
            style.set('fontId', str(len(fonts)))
            style.set('applyFont', '1')
            fonts.append(font)
            fonts.set('count', str(len(fonts)))
        else:
            style.set('numFmtId', '0')
            style.set('applyNumberFormat', '1')
        result = len(formats)
        formats.append(style)
        formats.set('count', str(len(formats)))
        mapping[style_id] = result
        return result

    root = parse_xml(parts[paths['Data']])
    sheet_data = root.find(tag('sheetData'))
    rows = {int(row.get('r')): row for row in sheet_data}
    header = rows.get(1)
    if header is None:
        raise ValueError('Missing Data header row')
    for cell in header.findall(tag('c')):
        cell.set('s', str(transformed_style(int(cell.get('s', '0')), bold=True)))

    retained = []
    seen = set()
    record_count = 0
    total = 0.0
    for original_row in sorted(rows):
        if original_row == 1:
            continue
        cells = [data.cell(original_row, col) for col in range(1, 6)]
        if all(c.value is None for c in cells):
            continue
        record_count += 1
        if record_count > bound:
            raise ValueError('Data record count exceeds row_bound')
        identity = cells[0].value
        if cells[0].data_type == 'f':
            raise ValueError('Formula IDs are unsupported')
        key = (type(identity).__name__, identity)
        if key in seen:
            continue
        seen.add(key)
        try:
            quantity, price = number(cells[2]), number(cells[3])
        except ValueError:
            continue
        if cells[1].data_type in ('f', 'e'):
            raise ValueError('Formula/error dates are unsupported')
        day = normalized_date(cells[1].value, book.epoch)
        amount = quantity * price
        if not math.isfinite(amount) or not math.isfinite(total + amount):
            raise ValueError('Calculated amount or total exceeds numeric range')
        total += amount
        output_row = len(retained) + 2
        row = copy.deepcopy(rows[original_row])
        row.set('r', str(output_row))
        for cell in row.findall(tag('c')):
            cell.set('r', re.sub(r'\d+$', str(output_row), cell.get('r')))
        for column, value in (('B', day), ('C', quantity), ('D', price)):
            cell = get_cell(row, f'{column}{output_row}')
            set_cell(cell, value, style=transformed_style(int(cell.get('s', '0'))))
        cell = get_cell(row, f'E{output_row}')
        set_cell(cell, amount, formula=f'C{output_row}*D{output_row}', style=transformed_style(int(cell.get('s', '0'))))
        retained.append(row)

    for row in list(sheet_data):
        if row is not header:
            sheet_data.remove(row)
    sheet_data.extend(retained)
    last_row = len(retained) + 1
    dimension = root.find(tag('dimension'))
    if dimension is not None:
        last_column = max((column_index(c.get('r')) for row in sheet_data for c in row.findall(tag('c'))), default=5)
        from openpyxl.utils import get_column_letter
        dimension.set('ref', f'A1:{get_column_letter(last_column)}{last_row}')
    auto_filter = root.find(tag('autoFilter'))
    if auto_filter is not None:
        auto_filter.set('ref', f'A1:E{last_row}')
    parts[paths['Data']] = xml_bytes(root)

    if 'Summary' in paths:
        summary_path = paths['Summary']
        summary = parse_xml(parts[summary_path])
    else:
        used_ids = {r.get('Id') for r in relationships}
        i = 1
        while f'rId{i}' in used_ids:
            i += 1
        rid = f'rId{i}'
        i = 1
        while f'xl/worksheets/sheet{i}.xml' in parts:
            i += 1
        summary_path = f'xl/worksheets/sheet{i}.xml'
        sheet_id = max(int(s.get('sheetId')) for s in sheets) + 1
        ET.SubElement(sheets, tag('sheet'), {'name': 'Summary', 'sheetId': str(sheet_id), '{' + R + '}id': rid})
        ET.SubElement(relationships, '{' + P + '}Relationship', {'Id': rid, 'Type': R + '/worksheet', 'Target': summary_path[3:]})
        types = parse_xml(parts['[Content_Types].xml'])
        ET.SubElement(types, '{' + C + '}Override', {'PartName': '/' + summary_path, 'ContentType': 'application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml'})
        parts['[Content_Types].xml'] = xml_bytes(types)
        summary = ET.Element(tag('worksheet'))
        ET.SubElement(summary, tag('sheetData'))
    summary_data = summary.find(tag('sheetData'))
    first = next((r for r in summary_data if r.get('r') == '1'), None)
    if first is None:
        first = ET.Element(tag('row'), {'r': '1'})
        summary_data.insert(0, first)
    set_cell(get_cell(first, 'A1'), 'Total')
    set_cell(get_cell(first, 'B1'), total, formula=f'SUM(Data!E2:E{last_row})')
    # Omitting dimension is valid and avoids a stale preexisting Summary extent.
    dimension = summary.find(tag('dimension'))
    if dimension is not None:
        summary.remove(dimension)
    parts[summary_path] = xml_bytes(summary)
    parts['xl/styles.xml'] = xml_bytes(styles)

    # Remove stale calculation ordering; generated formulas already have caches.
    parts.pop('xl/calcChain.xml', None)
    for rel in list(relationships):
        if rel.get('Type', '').endswith('/calcChain'):
            relationships.remove(rel)
    types = parse_xml(parts['[Content_Types].xml'])
    for child in list(types):
        if child.get('PartName') == '/xl/calcChain.xml':
            types.remove(child)
    parts['[Content_Types].xml'] = xml_bytes(types)
    calc = workbook.find(tag('calcPr'))
    if calc is None:
        calc = ET.SubElement(workbook, tag('calcPr'))
    calc.set('calcMode', 'auto')
    calc.set('fullCalcOnLoad', '1')
    parts['xl/workbook.xml'] = xml_bytes(workbook)
    parts['xl/_rels/workbook.xml.rels'] = xml_bytes(relationships)
    book.close()
    output = io.BytesIO()
    with zipfile.ZipFile(output, 'w', zipfile.ZIP_DEFLATED) as archive:
        for name, content in parts.items():
            archive.writestr(name, content)
    result = base64.b64encode(output.getvalue()).decode('ascii')
    if len(result) > 200000:
        raise ValueError('Output exceeds workbook_b64 size limit')
    return {'workbook_b64': result}


def main():
    payload = json.load(sys.stdin)
    json.dump(clean_workbook(payload), sys.stdout, ensure_ascii=False)
    sys.stdout.write('\n')


if __name__ == '__main__':
    main()
